import json, math
g = json.load(open('/bot/src/grid.json'))
score = {tuple(int(v) for v in k.split(',')): s for k, s in g.items()}
CELL=0.05
def st(c):
    s = score.get(c); return None if s is None else ('O' if s >= 2 else 'F')
occ = {c for c,s in score.items() if s>=2}
near_wall = set()
for c in occ:
    for dx in (-2,-1,0,1,2):
        for dy in (-2,-1,0,1,2): near_wall.add((c[0]+dx,c[1]+dy))
def nbrs(c):
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)): yield (c[0]+dx,c[1]+dy)
fr = [c for c in score if st(c)=='F' and c not in near_wall and any(st(n) is None for n in nbrs(c))]
# require the unknown neighbor region to be "big": count unknown cells within radius 3
def unk(c):
    return sum(1 for dx in range(-3,4) for dy in range(-3,4) if st((c[0]+dx,c[1]+dy)) is None)
fr = [c for c in fr if unk(c) >= 15]
# cluster by flood fill (8-conn) among frontier cells
frs = set(fr); clusters=[]
while frs:
    c = frs.pop(); stack=[c]; cl=[c]
    while stack:
        a = stack.pop()
        for dx in (-1,0,1):
            for dy in (-1,0,1):
                n=(a[0]+dx,a[1]+dy)
                if n in frs: frs.remove(n); stack.append(n); cl.append(n)
    clusters.append(cl)
clusters.sort(key=len, reverse=True)
for cl in clusters[:15]:
    cx = sum(c[0] for c in cl)/len(cl)*CELL; cy = sum(c[1] for c in cl)/len(cl)*CELL
    # direction of unknown: average offset of unknown neighbors
    ux=uy=0
    for c in cl:
        for dx in range(-3,4):
            for dy in range(-3,4):
                if st((c[0]+dx,c[1]+dy)) is None: ux+=dx; uy+=dy
    ang = math.degrees(math.atan2(uy,ux))
    d = 'N' if 45<=ang<135 else 'W' if 135<=ang or ang<-135 else 'S' if -135<=ang<-45 else 'E'
    print('size %3d at (%.2f,%.2f) unknown toward %s (%.0f deg)' % (len(cl), cx, cy, d, ang))
